mapper.select:
SELECT id, comment_id, post_id, user_id, root_id, parent_id, reply_to_user_id,
       content, status, deleted, created_at, updated_at
FROM post_comments
WHERE post_id = #{postId}
  AND deleted = 0
  AND status = 1

  AND comment_id < #{cursorCommentId}

ORDER BY comment_id DESC
LIMIT #{limit}
